package com.edunexa.app
import android.os.Bundle
import android.text.InputType
import android.widget.*
import androidx.appcompat.app.AppCompatActivity
import com.edunexa.app.data.ResultRepository
class ResultCalculatorActivity:AppCompatActivity(){private val repo=ResultRepository();private fun grade(p:Double)=when{p>=90->"A+";p>=80->"A";p>=70->"B+";p>=60->"B";p>=50->"C";p>=33->"D";else->"F"};override fun onCreate(b:Bundle?){super.onCreate(b);val r=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(36,36,36,36)};r.addView(TextView(this).apply{text="Result Calculator";textSize=26f;setTypeface(typeface,1)});val got=EditText(this).apply{hint="Obtained marks";inputType=InputType.TYPE_CLASS_NUMBER or InputType.TYPE_NUMBER_FLAG_DECIMAL};val total=EditText(this).apply{hint="Total marks";inputType=got.inputType};val out=TextView(this).apply{textSize=20f;setPadding(0,18,0,18)};r.addView(got);r.addView(total);r.addView(Button(this).apply{text="Calculate & Save";setOnClickListener{val a=got.text.toString().toDoubleOrNull();val t=total.text.toString().toDoubleOrNull();if(a==null||t==null||t<=0||a<0||a>t){out.text="Enter valid marks";return@setOnClickListener};val p=a*100/t;val g=grade(p);out.text="%.2f%% • Grade %s".format(p,g);repo.save(a,t,p,g){_,m->Toast.makeText(this@ResultCalculatorActivity,m,Toast.LENGTH_SHORT).show()}}});r.addView(out);r.addView(TextView(this).apply{text="Recent History";textSize=20f;setTypeface(typeface,1)});val history=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};r.addView(history);repo.history({rows->if(rows.isEmpty())history.addView(TextView(this).apply{text="No saved results yet"}) else rows.take(20).forEach{x->history.addView(TextView(this).apply{text="${x["obtained"]}/${x["total"]} • ${"%.2f".format((x["percentage"] as? Number)?.toDouble()?:0.0)}% • ${x["grade"]}";setPadding(0,10,0,10)})}},{history.addView(TextView(this).apply{text=it})});setContentView(ScrollView(this).apply{addView(r)})}}
